SELECT "posts"."id","posts"."user_id","posts"."created_at","posts"."updated_at","posts"."title","posts"."content","Author"."id" AS "Author__id","Author"."created_at" AS "Author__created_at","Author"."updated_at" AS "Author__updated_at","Author"."address" AS "Author__address","Author"."birthday" AS "Author__birthday","Author"."email" AS "Author__email","Author"."email_verified" AS "Author__email_verified","Author"."first_name" AS "Author__first_name","Author"."gender" AS "Author__gender","Author"."last_name" AS "Author__last_name" FROM "posts" LEFT JOIN "users" "Author" ON "posts"."user_id" = "Author"."id" WHERE posts.id = $1 ORDER BY "posts"."id" LIMIT $2;
